function layoutDayLessons(dayLessons){const sorted=[...dayLessons].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)||new Date(a.ends_at)-new Date(b.ends_at));const groups=[];let group=[],groupEnd=null;for(const l of sorted){const st=new Date(l.starts_at),en=new Date(l.ends_at);if(!group.length||st<groupEnd){group.push(l);if(!groupEnd||en>groupEnd)groupEnd=en}else{groups.push(group);group=[l];groupEnd=en}}if(group.length)groups.push(group);const result=new Map();for(const g of groups){const colEnds=[];const assigned=[];for(const l of g){const st=new Date(l.starts_at),en=new Date(l.ends_at);let col=colEnds.findIndex(x=>x<=st);if(col<0)col=colEnds.length;colEnds[col]=en;assigned.push([l,col])}const cols=Math.max(1,colEnds.length);for(const [l,col] of assigned)result.set(l.id,{col,cols})}return result}
